import{_ as p,a0 as o,w as d,s as r,I as n,x as a,a1 as e,A as t,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const $=JSON.parse('{"title":"如何构建一台网络引导服务器（一） | LCTT x X-CMD","titleTemplate":false,"description":"如何构建一台网络引导服务器（一） | LCTT (201812) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何构建一台网络引导服务器（一） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何构建一台网络引导服务器（一） | LCTT (201812) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201812/20181123 How to Build a Netboot Server, Part 1","title":"如何构建一台网络引导服务器（一）","tag":"201812","desc":""},"relativePath":"201812/20181123 How to Build a Netboot Server, Part 1.md","filePath":"[post].md"}'),c={name:"201812/20181123 How to Build a Netboot Server, Part 1.md"};function h(g,s,k,u,b,f){const i=o("Link");return d(),r("div",null,[s[42]||(s[42]=n("h1",{id:"如何构建一台网络引导服务器-一",tabindex:"-1"},[a("如何构建一台网络引导服务器（一） "),n("a",{class:"header-anchor",href:"#如何构建一台网络引导服务器-一","aria-label":"Permalink to “如何构建一台网络引导服务器（一）”"},"​")],-1)),s[43]||(s[43]=n("p",null,[n("img",{src:"https://fedoramagazine.org/wp-content/uploads/2018/11/build-netboot-816x345.jpg",alt:""})],-1)),n("p",null,[s[1]||(s[1]=a("有些计算机网络需要在各个物理机器上维护相同的软件和配置。学校的计算机实验室就是这样的一个环境。 ",-1)),e(i,{href:"https://en.wikipedia.org/wiki/Network_booting"},{default:t(()=>[...s[0]||(s[0]=[a("网络引导",-1)])]),_:1}),s[2]||(s[2]=a(" 服务器能够被配置为基于网络去提供一个完整的操作系统，以便于客户端计算机从一个中央位置获取配置。本教程将向你展示构建一台网络引导服务器的一种方法。",-1))]),s[44]||(s[44]=n("p",null,"本教程的第一部分将包括创建一台网络引导服务器和镜像。第二部分将展示如何去添加 Kerberos 验证的家目录到网络引导配置中。",-1)),s[45]||(s[45]=n("h3",{id:"初始化配置",tabindex:"-1"},[a("初始化配置 "),n("a",{class:"header-anchor",href:"#初始化配置","aria-label":"Permalink to “初始化配置”"},"​")],-1)),n("p",null,[s[4]||(s[4]=a("首先去下载 Fedora 服务器的 ",-1)),e(i,{href:"https://dl.fedoraproject.org/pub/fedora/linux/releases/28/Server/x86_64/iso/"},{default:t(()=>[...s[3]||(s[3]=[a("netinst",-1)])]),_:1}),s[5]||(s[5]=a(" 镜像，将它刻录到一张光盘上，然后用它引导服务器来重新格式化。我们只需要一个典型的 Fedora Server 的“最小化安装”来作为我们的开端，安装完成后，我们可以使用命令行去添加我们需要的任何额外的包。",-1))]),s[46]||(s[46]=l(`<p><img src="https://fedoramagazine.org/wp-content/uploads/2018/11/installation-summary-1024x768.png" alt=""></p><blockquote><p>注意：本教程中我们将使用 Fedora 28。其它版本在“最小化安装”中包含的包可能略有不同。如果你使用的是不同的 Fedora 版本，如果一个预期的文件或命令不可用，你可能需要做一些调试。</p></blockquote><p>最小化安装的 Fedora Server 运行起来之后，以 root 用户登入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo -i</span></span></code></pre></div><p>并设置主机名字：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ MY_HOSTNAME=server-01.example.edu</span></span>
<span class="line"><span>$ hostnamectl set-hostname $MY_HOSTNAME</span></span></code></pre></div>`,6)),n("blockquote",null,[n("p",null,[s[7]||(s[7]=a("注意：Red Hat 建议静态和临时名字应都要与这个机器在 DNS 中的完全合格域名相匹配，比如 host.example.com（",-1)),e(i,{href:"https://docs.fedoraproject.org/en-US/Fedora/25/html/Networking_Guide/ch-Configure_Host_Names.html#sec_Understanding_Host_Names"},{default:t(()=>[...s[6]||(s[6]=[a("了解主机名字",-1)])]),_:1}),s[8]||(s[8]=a("）。",-1))]),s[9]||(s[9]=n("p",null,[a("注意：本指南为了方便“复制粘贴”。需要自定义的任何值都声明为一个 "),n("code",null,"MY_*"),a(" 变量，在你运行剩余命令之前，你可能需要调整它。如果你注销之后，变量的赋值将被清除。")],-1)),s[10]||(s[10]=n("p",null,[a("注意：Fedora 28 Server 在默认情况下往往会转储大量的日志到控制台上。你可以通过运行命令："),n("code",null,"sysctl -w kernel.printk=0"),a(" 去禁用控制台日志输出。")],-1))]),s[47]||(s[47]=l(`<p>接下来，我们需要在我们的服务器上配置一个静态网络地址。运行下面的一系列命令将找到并重新配置你的默认网络连接：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ MY_DNS1=192.0.2.91</span></span>
<span class="line"><span>$ MY_DNS2=192.0.2.92</span></span>
<span class="line"><span>$ MY_IP=192.0.2.158</span></span>
<span class="line"><span>$ MY_PREFIX=24</span></span>
<span class="line"><span>$ MY_GATEWAY=192.0.2.254</span></span>
<span class="line"><span>$ DEFAULT_DEV=$(ip route show default | awk &#39;{print $5}&#39;)</span></span>
<span class="line"><span>$ DEFAULT_CON=$(nmcli d show $DEFAULT_DEV | sed -n &#39;/^GENERAL.CONNECTION:/s!.*:\\s*!! p&#39;)</span></span>
<span class="line"><span>$ nohup bash &lt;&lt; END</span></span>
<span class="line"><span>nmcli con mod &quot;$DEFAULT_CON&quot; connection.id &quot;$DEFAULT_DEV&quot;</span></span>
<span class="line"><span>nmcli con mod &quot;$DEFAULT_DEV&quot; connection.interface-name &quot;$DEFAULT_DEV&quot;</span></span>
<span class="line"><span>nmcli con mod &quot;$DEFAULT_DEV&quot; ipv4.method disabled</span></span>
<span class="line"><span>nmcli con up &quot;$DEFAULT_DEV&quot;</span></span>
<span class="line"><span>nmcli con add con-name br0 ifname br0 type bridge</span></span>
<span class="line"><span>nmcli con mod br0 bridge.stp no</span></span>
<span class="line"><span>nmcli con mod br0 ipv4.dns $MY_DNS1,$MY_DNS2</span></span>
<span class="line"><span>nmcli con mod br0 ipv4.addresses $MY_IP/$MY_PREFIX</span></span>
<span class="line"><span>nmcli con mod br0 ipv4.gateway $MY_GATEWAY</span></span>
<span class="line"><span>nmcli con mod br0 ipv4.method manual</span></span>
<span class="line"><span>nmcli con up br0</span></span>
<span class="line"><span>nmcli con add con-name br0-slave0 ifname &quot;$DEFAULT_DEV&quot; type bridge-slave master br0</span></span>
<span class="line"><span>nmcli con up br0-slave0</span></span>
<span class="line"><span>END</span></span></code></pre></div>`,2)),n("blockquote",null,[s[14]||(s[14]=n("p",null,[a("注意：上面最后的一组命令被封装到一个 "),n("code",null,"nohup"),a(" 脚本中，因为它将临时禁用网络。这个 "),n("code",null,"nohup"),a(" 命令可以让 "),n("code",null,"nmcli"),a(" 命令运行完成，即使你的 SSH 连接断开。注意，连接恢复可能需要 10 秒左右的时间，如果你改变了服务器 IP 地址，你将需要重新启动一个新的 SSH 连接。")],-1)),n("p",null,[s[12]||(s[12]=a("注意：上面的网络配置在默认的连接之上创建了一个 ",-1)),e(i,{href:"https://en.wikipedia.org/wiki/Bridging_(networking)"},{default:t(()=>[...s[11]||(s[11]=[a("网桥",-1)])]),_:1}),s[13]||(s[13]=a("，这样我们在后面的测试中就可以直接运行一个虚拟机实例。如果你不想在这台服务器上去直接测试网络引导镜像，你可以跳过创建网桥的命令，并直接在你的默认网络连接上配置静态 IP 地址。",-1))])]),s[48]||(s[48]=l('<h3 id="安装和配置-nfs4" tabindex="-1">安装和配置 NFS4 <a class="header-anchor" href="#安装和配置-nfs4" aria-label="Permalink to “安装和配置 NFS4”">​</a></h3><p>从安装 nfs-utils 包开始：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dnf install -y nfs-utils</span></span></code></pre></div>',3)),n("p",null,[s[16]||(s[16]=a("为发布 NFS 去创建一个顶级的 ",-1)),e(i,{href:"https://www.centos.org/docs/5/html/5.1/Deployment_Guide/s3-nfs-server-config-exportfs-nfsv4.html"},{default:t(()=>[...s[15]||(s[15]=[a("伪文件系统",-1)])]),_:1}),s[17]||(s[17]=a("，然后在你的网络上共享它：",-1))]),s[49]||(s[49]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ MY_SUBNET=192.0.2.0</span></span>
<span class="line"><span>$ mkdir /export</span></span>
<span class="line"><span>$ echo &quot;/export -fsid=0,ro,sec=sys,root_squash $MY_SUBNET/$MY_PREFIX&quot; &gt; /etc/exports</span></span></code></pre></div><p>SELinux 会干扰网络引导服务器的运行。为它配置例外规则超出了本教程中，因此我们这里直接禁用它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sed -i &#39;/GRUB_CMDLINE_LINUX/s/&quot;$/ audit=0 selinux=0&quot;/&#39; /etc/default/grub</span></span>
<span class="line"><span>$ grub2-mkconfig -o /boot/grub2/grub.cfg</span></span>
<span class="line"><span>$ sed -i &#39;s/SELINUX=enforcing/SELINUX=disabled/&#39; /etc/sysconfig/selinux</span></span>
<span class="line"><span>$ setenforce 0</span></span></code></pre></div><blockquote><p>注意：应该不需要编辑 grub 命令行，但我们在测试过程中发现，直接编辑 <code>/etc/sysconfig/selinux</code> 被证明重启后是无效的，因此这样做再次确保设置了 <code>selinux=0</code> 标志。</p></blockquote><p>现在，在本地防火墙中为 NFS 服务添加一个例外规则，然后启动 NFS 服务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ firewall-cmd --add-service nfs</span></span>
<span class="line"><span>$ firewall-cmd --runtime-to-permanent</span></span>
<span class="line"><span>$ systemctl enable nfs-server.service</span></span>
<span class="line"><span>$ systemctl start nfs-server.service</span></span></code></pre></div><h3 id="创建网络引导镜像" tabindex="-1">创建网络引导镜像 <a class="header-anchor" href="#创建网络引导镜像" aria-label="Permalink to “创建网络引导镜像”">​</a></h3><p>现在我们的 NFS 服务器已经启动运行了，我们需要为它提供一个操作系统镜像，以便于它提供给客户端计算机。我们将从一个非常小的镜像开始，等一切顺利之后再添加。</p><p>首先，创建一个存放我们镜像的新目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir /fc28</span></span></code></pre></div><p>使用 <code>dnf</code> 命令在新目录下用几个基础包去构建镜像：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dnf -y --releasever=28 --installroot=/fc28 install fedora-release systemd passwd rootfiles sudo dracut dracut-network nfs-utils vim-minimal dnf</span></span></code></pre></div><p>在上面的命令中省略了很重要的 <code>kernel</code> 包。在它们被安装完成之前，我们需要去调整一下 <code>initramfs</code> 镜像中包含的驱动程序集，<code>kernel</code> 首次安装时将自动构建这个镜像。尤其是，我们需要禁用 <code>hostonly</code> 模式，以便于 <code>initramfs</code> 镜像能够在各种硬件平台上正常工作，并且我们还需要添加对网络和 NFS 的支持：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &#39;hostonly=no&#39; &gt; /fc28/etc/dracut.conf.d/hostonly.conf</span></span>
<span class="line"><span>$ echo &#39;add_dracutmodules+=&quot; network nfs &quot;&#39; &gt; /fc28/etc/dracut.conf.d/netboot.conf</span></span></code></pre></div><p>现在，安装 <code>kernel</code> 包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dnf -y --installroot=/fc28 install kernel</span></span></code></pre></div><p>设置一个阻止 <code>kernel</code> 包被更新的规则：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &#39;exclude=kernel-*&#39; &gt;&gt; /fc28/etc/dnf/dnf.conf</span></span></code></pre></div><p>设置 locale：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &#39;LANG=&quot;en_US.UTF-8&quot;&#39; &gt; /fc28/etc/locale.conf</span></span></code></pre></div><blockquote><p>注意：如果 locale 没有正确配置，一些程序（如 GNOME Terminal）将无法正常工作。</p></blockquote><p>设置客户端的主机名字：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ MY_CLIENT_HOSTNAME=client-01.example.edu</span></span>
<span class="line"><span>$ echo $MY_CLIENT_HOSTNAME &gt; /fc28/etc/hostname</span></span></code></pre></div><p>禁用控制台日志输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &#39;kernel.printk = 0 4 1 7&#39; &gt; /fc28/etc/sysctl.d/00-printk.conf</span></span></code></pre></div><p>定义网络引导镜像中的本地 <code>liveuser</code> 用户：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &#39;liveuser:x:1000:1000::/home/liveuser:/bin/bash&#39; &gt;&gt; /fc28/etc/passwd</span></span>
<span class="line"><span>$ echo &#39;liveuser::::::::&#39; &gt;&gt; /fc28/etc/shadow</span></span>
<span class="line"><span>$ echo &#39;liveuser:x:1000:&#39; &gt;&gt; /fc28/etc/group</span></span>
<span class="line"><span>$ echo &#39;liveuser:!::&#39; &gt;&gt; /fc28/etc/gshadow</span></span></code></pre></div><p>允许 <code>liveuser</code> 使用 <code>sudo</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &#39;liveuser ALL=(ALL) NOPASSWD: ALL&#39; &gt; /fc28/etc/sudoers.d/liveuser</span></span></code></pre></div><p>启用自动创建家目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dnf install -y --installroot=/fc28 authselect oddjob-mkhomedir</span></span>
<span class="line"><span>$ echo &#39;dirs /home&#39; &gt; /fc28/etc/rwtab.d/home</span></span>
<span class="line"><span>$ chroot /fc28 authselect select sssd with-mkhomedir --force</span></span>
<span class="line"><span>$ chroot /fc28 systemctl enable oddjobd.service</span></span></code></pre></div><p>由于多个客户端将会同时挂载我们的镜像，我们需要去配置镜像工作在只读模式中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sed -i &#39;s/^READONLY=no$/READONLY=yes/&#39; /fc28/etc/sysconfig/readonly-root</span></span></code></pre></div><p>配置日志输出到内存而不是持久存储中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sed -i &#39;s/^#Storage=auto$/Storage=volatile/&#39; /fc28/etc/systemd/journald.conf</span></span></code></pre></div><p>配置 DNS：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ MY_DNS1=192.0.2.91</span></span>
<span class="line"><span>$ MY_DNS2=192.0.2.92</span></span>
<span class="line"><span>$ cat &lt;&lt; END &gt; /fc28/etc/resolv.conf</span></span>
<span class="line"><span>nameserver $MY_DNS1</span></span>
<span class="line"><span>nameserver $MY_DNS2</span></span>
<span class="line"><span>END</span></span></code></pre></div>`,37)),n("p",null,[s[19]||(s[19]=a("绕开编写本教程时存在的根目录只读挂载的 bug（",-1)),e(i,{href:"https://bugzilla.redhat.com/show_bug.cgi?id=1542567"},{default:t(()=>[...s[18]||(s[18]=[a("BZ1542567",-1)])]),_:1}),s[20]||(s[20]=a("）：",-1))]),s[50]||(s[50]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &#39;dirs /var/lib/gssproxy&#39; &gt; /fc28/etc/rwtab.d/gssproxy</span></span>
<span class="line"><span>$ cat &lt;&lt; END &gt; /fc28/etc/rwtab.d/systemd</span></span>
<span class="line"><span>dirs /var/lib/systemd/catalog</span></span>
<span class="line"><span>dirs /var/lib/systemd/coredump</span></span>
<span class="line"><span>END</span></span></code></pre></div><p>最后，为我们镜像创建 NFS 文件系统，并将它共享到我们的子网中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir /export/fc28</span></span>
<span class="line"><span>$ echo &#39;/fc28 /export/fc28 none bind 0 0&#39; &gt;&gt; /etc/fstab</span></span>
<span class="line"><span>$ mount /export/fc28</span></span>
<span class="line"><span>$ echo &quot;/export/fc28 -ro,sec=sys,no_root_squash $MY_SUBNET/$MY_PREFIX&quot; &gt; /etc/exports.d/fc28.exports</span></span>
<span class="line"><span>$ exportfs -vr</span></span></code></pre></div><h3 id="创建引导加载器" tabindex="-1">创建引导加载器 <a class="header-anchor" href="#创建引导加载器" aria-label="Permalink to “创建引导加载器”">​</a></h3>`,4)),n("p",null,[s[22]||(s[22]=a("现在，我们已经有了可以进行网络引导的操作系统，我们需要一个引导加载器去从客户端系统上启动它。在本教程中我们使用的是 ",-1)),e(i,{href:"https://ipxe.org/"},{default:t(()=>[...s[21]||(s[21]=[a("iPXE",-1)])]),_:1}),s[23]||(s[23]=a("。",-1))]),s[51]||(s[51]=l(`<blockquote><p>注意：本节和接下来的节使用 QEMU 测试，也能在另外一台单独的计算机上来完成；它们并不需要在网络引导服务器上来运行。</p></blockquote><p>安装 <code>git</code> 并使用它去下载 iPXE：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dnf install -y git</span></span>
<span class="line"><span>$ git clone http://git.ipxe.org/ipxe.git $HOME/ipxe</span></span></code></pre></div><p>现在我们需要去为我们的引导加载器创建一个指定的启动脚本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat &lt;&lt; &#39;END&#39; &gt; $HOME/ipxe/init.ipxe</span></span>
<span class="line"><span>#!ipxe</span></span>
<span class="line"><span></span></span>
<span class="line"><span>prompt --key 0x02 --timeout 2000 Press Ctrl-B for the iPXE command line... &amp;&amp; shell ||</span></span>
<span class="line"><span></span></span>
<span class="line"><span>dhcp || exit</span></span>
<span class="line"><span>set prefix file:///linux</span></span>
<span class="line"><span>chain \${prefix}/boot.cfg || exit</span></span>
<span class="line"><span>END</span></span></code></pre></div><p>启动 “file” 下载协议：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &#39;#define DOWNLOAD_PROTO_FILE&#39; &gt; $HOME/ipxe/src/config/local/general.h</span></span></code></pre></div><p>安装 C 编译器以及相关的工具和库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dnf groupinstall -y &quot;C Development Tools and Libraries&quot;</span></span></code></pre></div><p>构建引导加载器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd $HOME/ipxe/src</span></span>
<span class="line"><span>$ make clean</span></span>
<span class="line"><span>$ make bin-x86_64-efi/ipxe.efi EMBED=../init.ipxe</span></span></code></pre></div><p>记下新编译的引导加载器的存储位置。我们将在接下来的节中用到它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ IPXE_FILE=&quot;$HOME/ipxe/src/bin-x86_64-efi/ipxe.efi&quot;</span></span></code></pre></div><h3 id="用-qemu-测试" tabindex="-1">用 QEMU 测试 <a class="header-anchor" href="#用-qemu-测试" aria-label="Permalink to “用 QEMU 测试”">​</a></h3>`,14)),n("p",null,[s[25]||(s[25]=a("这一节是可选的，但是你需要去复制下面显示在物理机器上的 ",-1)),e(i,{href:"https://en.wikipedia.org/wiki/EFI_system_partition"},{default:t(()=>[...s[24]||(s[24]=[a("EFI 系统分区",-1)])]),_:1}),s[26]||(s[26]=a(" 的布局，在网络引导时需要去配置它们。",-1))]),s[52]||(s[52]=l(`<blockquote><p>注意：如果你想实现一个完全的无盘系统，你也可以复制那个文件到一个 TFTP 服务器，然后从 DHCP 上指向那台服务器。</p></blockquote><p>为了使用 QEMU 去测试我们的引导加载器，我们继续去创建一个仅包含一个 EFI 系统分区和我们的启动文件的、很小的磁盘镜像。</p><p>从创建 EFI 系统分区所需要的目录布局开始，然后把我们在前面节中创建的引导加载器复制进去：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir -p $HOME/esp/efi/boot</span></span>
<span class="line"><span>$ mkdir $HOME/esp/linux</span></span>
<span class="line"><span>$ cp $IPXE_FILE $HOME/esp/efi/boot/bootx64.efi</span></span></code></pre></div><p>下面的命令将识别我们的引导加载器镜像正在使用的内核版本，并将它保存到一个变量中，以备后续的配置命令去使用它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ DEFAULT_VER=$(ls -c /fc28/lib/modules | head -n 1)</span></span></code></pre></div><p>定义我们的客户端计算机将使用的引导配置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ MY_DNS1=192.0.2.91</span></span>
<span class="line"><span>$ MY_DNS2=192.0.2.92</span></span>
<span class="line"><span>$ MY_NFS4=server-01.example.edu</span></span>
<span class="line"><span>$ cat &lt;&lt; END &gt; $HOME/esp/linux/boot.cfg</span></span>
<span class="line"><span>#!ipxe</span></span>
<span class="line"><span></span></span>
<span class="line"><span>kernel --name kernel.efi \\\${prefix}/vmlinuz-$DEFAULT_VER initrd=initrd.img ro ip=dhcp rd.peerdns=0 nameserver=$MY_DNS1 nameserver=$MY_DNS2 root=nfs4:$MY_NFS4:/fc28 console=tty0 console=ttyS0,115200n8 audit=0 selinux=0 quiet</span></span>
<span class="line"><span>initrd --name initrd.img \\\${prefix}/initramfs-$DEFAULT_VER.img</span></span>
<span class="line"><span>boot || exit</span></span>
<span class="line"><span>END</span></span></code></pre></div><blockquote><p>注意：上面的引导脚本展示了如何使用 iPXE 去网络引导 Linux 的最小示例。还可以做更多更复杂的配置。值得注意的是，iPXE 支持交互式引导菜单，它可以让你配置默认选项和超时时间。比如，一个更高级一点 iPXE 脚本可以默认从本地磁盘引导一个操作系统，如果在倒计时结束之前用户按下了一个键，才会去网络引导一个操作系统。</p></blockquote><p>复制 Linux 内核并分配 initramfs 给 EFI 系统分区：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cp $(find /fc28/lib/modules -maxdepth 2 -name &#39;vmlinuz&#39; | grep -m 1 $DEFAULT_VER) $HOME/esp/linux/vmlinuz-$DEFAULT_VER</span></span>
<span class="line"><span>$ cp $(find /fc28/boot -name &#39;init*&#39; | grep -m 1 $DEFAULT_VER) $HOME/esp/linux/initramfs-$DEFAULT_VER.img</span></span></code></pre></div><p>我们最终的目录布局应该看起来像下面的样子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>esp</span></span>
<span class="line"><span>├── efi</span></span>
<span class="line"><span>│   └── boot</span></span>
<span class="line"><span>│   └── bootx64.efi</span></span>
<span class="line"><span>└── linux</span></span>
<span class="line"><span> ├── boot.cfg</span></span>
<span class="line"><span> ├── initramfs-4.18.18-200.fc28.x86_64.img</span></span>
<span class="line"><span> └── vmlinuz-4.18.18-200.fc28.x86_64</span></span></code></pre></div><p>要让 QEMU 去使用我们的 EFI 系统分区，我们需要去创建一个小的 <code>uefi.img</code> 磁盘镜像来包含它，然后将它连接到 QEMU 作为主引导驱动器。</p><p>开始安装必需的工具：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dnf install -y parted dosfstools</span></span></code></pre></div><p>现在创建 <code>uefi.img</code> 文件，并将 <code>esp</code> 目录中的文件复制进去：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ESP_SIZE=$(du -ks $HOME/esp | cut -f 1)</span></span>
<span class="line"><span>$ dd if=/dev/zero of=$HOME/uefi.img count=$((\${ESP_SIZE}+5000)) bs=1KiB</span></span>
<span class="line"><span>$ UEFI_DEV=$(losetup --show -f $HOME/uefi.img)</span></span>
<span class="line"><span>$ parted \${UEFI_DEV} -s mklabel gpt mkpart EFI FAT16 1MiB 100% toggle 1 boot</span></span>
<span class="line"><span>$ mkfs -t msdos \${UEFI_DEV}p1</span></span>
<span class="line"><span>$ mkdir -p $HOME/mnt</span></span>
<span class="line"><span>$ mount \${UEFI_DEV}p1 $HOME/mnt</span></span>
<span class="line"><span>$ cp -r $HOME/esp/* $HOME/mnt</span></span>
<span class="line"><span>$ umount $HOME/mnt</span></span>
<span class="line"><span>$ losetup -d \${UEFI_DEV}</span></span></code></pre></div><blockquote><p>注意：在物理计算机上，你只需要从 <code>esp</code> 目录中复制文件到计算机上已存在的 EFI 系统分区中。你不需要使用 <code>uefi.img</code> 文件去引导物理计算机。</p><p>注意：在一个物理计算机上，如果文件名已存在，你可以重命名 <code>bootx64.efi</code> 文件，如果你重命名了它，就需要去编辑计算机的 BIOS 设置，并添加重命令后的 efi 文件到引导列表中。</p></blockquote><p>接下来我们需要去安装 qemu 包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dnf install -y qemu-system-x86</span></span></code></pre></div><p>允许 QEMU 访问我们在本教程“初始化配置”一节中创建的网桥：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &#39;allow br0&#39; &gt; /etc/qemu/bridge.conf</span></span></code></pre></div><p>创建一个 <code>OVMF_VARS.fd</code> 镜像的副本去保存我们虚拟机的持久 BIOS 配置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cp /usr/share/edk2/ovmf/OVMF_VARS.fd $HOME</span></span></code></pre></div><p>现在，启动虚拟机：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ qemu-system-x86_64 -machine accel=kvm -nographic -m 1024 -drive if=pflash,format=raw,unit=0,file=/usr/share/edk2/ovmf/OVMF_CODE.fd,readonly=on -drive if=pflash,format=raw,unit=1,file=$HOME/OVMF_VARS.fd -drive if=ide,format=raw,file=$HOME/uefi.img -net bridge,br=br0 -net nic,model=virtio</span></span></code></pre></div><p>如果一切顺利，你将看到类似下图所示的结果：</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2018/11/netboot-liveuser-1024x641.png" alt=""></p><p>你可以使用 <code>shutdown</code> 命令关闭虚拟机回到我们的服务器上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo shutdown -h now</span></span></code></pre></div><blockquote><p>注意：如果出现了错误或虚拟机挂住了，你可能需要启动一个新的 SSH 会话去连接服务器，使用 <code>kill</code> 命令去终止 <code>qemu-system-x86_64</code> 进程。</p></blockquote><h3 id="镜像中添加包" tabindex="-1">镜像中添加包 <a class="header-anchor" href="#镜像中添加包" aria-label="Permalink to “镜像中添加包”">​</a></h3><p>镜像中添加包应该是一个很简单的问题，在服务器上 <code>chroot</code> 进镜像，然后运行 <code>dnf install &lt;package_name&gt;</code>。</p><p>在网络引导镜像中并不限制你能安装什么包。一个完整的图形化安装应该能够完美地工作。</p><p>下面是一个如何将最小化安装的网络引导镜像变成完整的图形化安装的示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ for i in dev dev/pts dev/shm proc sys run; do mount -o bind /$i /fc28/$i; done</span></span>
<span class="line"><span>$ chroot /fc28 /usr/bin/bash --login</span></span>
<span class="line"><span>$ dnf -y groupinstall &quot;Fedora Workstation&quot;</span></span>
<span class="line"><span>$ dnf -y remove gnome-initial-setup</span></span>
<span class="line"><span>$ systemctl disable sshd.service</span></span>
<span class="line"><span>$ systemctl enable gdm.service</span></span>
<span class="line"><span>$ systemctl set-default graphical.target</span></span>
<span class="line"><span>$ sed -i &#39;s/SELINUX=enforcing/SELINUX=disabled/&#39; /etc/sysconfig/selinux</span></span>
<span class="line"><span>$ logout</span></span>
<span class="line"><span>$ for i in run sys proc dev/shm dev/pts dev; do umount /fc28/$i; done</span></span></code></pre></div><p>可选地，你可能希望去启用 <code>liveuser</code> 用户的自动登录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sed -i &#39;/daemon/a AutomaticLoginEnable=true&#39; /fc28/etc/gdm/custom.conf</span></span>
<span class="line"><span>$ sed -i &#39;/daemon/a AutomaticLogin=liveuser&#39; /fc28/etc/gdm/custom.conf</span></span></code></pre></div><hr>`,40)),n("p",null,[s[28]||(s[28]=a("via: ",-1)),e(i,{href:"https://fedoramagazine.org/how-to-build-a-netboot-server-part-1/"},{default:t(()=>[...s[27]||(s[27]=[a("https://fedoramagazine.org/how-to-build-a-netboot-server-part-1/",-1)])]),_:1})]),n("p",null,[s[33]||(s[33]=a("作者：",-1)),e(i,{href:"https://fedoramagazine.org/author/glb/"},{default:t(()=>[...s[29]||(s[29]=[a("Gregory Bartholomew",-1)])]),_:1}),s[34]||(s[34]=a(" 选题：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[30]||(s[30]=[a("lujun9972",-1)])]),_:1}),s[35]||(s[35]=a(" 译者：",-1)),e(i,{href:"https://github.com/qhwdw"},{default:t(()=>[...s[31]||(s[31]=[a("qhwdw",-1)])]),_:1}),s[36]||(s[36]=a(" 校对：",-1)),e(i,{href:"https://github.com/wxy"},{default:t(()=>[...s[32]||(s[32]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[39]||(s[39]=a("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[37]||(s[37]=[a("LCTT",-1)])]),_:1}),s[40]||(s[40]=a(" 原创编译，",-1)),e(i,{href:"https://linux.cn/"},{default:t(()=>[...s[38]||(s[38]=[a("Linux中国",-1)])]),_:1}),s[41]||(s[41]=a(" 荣誉推出",-1))])])}const v=p(c,[["render",h]]);export{$ as __pageData,v as default};
